INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64882267', 64882267, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KOTA JAMBI', 'Pencetakan Spanduk Dalam Rangka Sosialisasi Desa Cantik di Kab/Kota', 'Barang', 'Pengadaan Langsung', 'Jambi, Jambi (Kota)', 270000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '2 SET', 'Pencetakan Spanduk Dalam Rangka Sosialisasi Desa Cantik di Kab/Kota', 'Ruang lingkup kegiatan meliputi pencetakan spanduk dalam rangka pelaksanaan pembinaan Desa Cantik (Desa Cinta Statistik), yang digunakan sebagai media informasi dan sosialisasi kegiatan. Pencetakan spanduk dilaksanakan sesuai dengan kebutuhan kegiatan, menggunakan bahan yang berkualitas, hasil cetak jelas dan tidak mudah luntur, serta dilengkapi dengan finishing yang memadai agar layak digunakan baik di dalam maupun di luar ruangan.Spanduk dicetak dengan ukuran standar kegiatan sosialisasi, desain full color yang informatif, serta memuat identitas kegiatan Pembinaan Desa Cantik, logo Badan Pusat Statistik (BPS), nama kabupaten/kota, dan tahun pelaksanaan. Pekerjaan pencetakan meliputi proses digital printing resolusi tinggi, finishing berupa jahit atau las keliling serta pemasangan mata ayam, hingga pengemasan dan pengiriman ke lokasi yang ditentukan.Pelaksanaan kegiatan dilaksanakan secara tepat waktu, tertib administrasi, dan dapat dipertanggungjawabkan, dengan berpedoman pada prinsip efisien, efektif, transparan, dan akuntabel, serta sesuai dengan ketentuan peraturan perundang-undangan, pengadaan barang/jasa pemerintah, dan kebijakan internal Badan Pusat Statistik (BPS).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1800740);
