INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64843963', 64843963, 'analyze_legacy', 'Kab. Blitar', 'kabkota', 'RSUD Ngudi Waluyo Wlingi', 'BELANJA JASA PEMBERSIHAN, PENGENDALIAN HAMA, DAN FUMIGASI - PEST CONTROL', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Blitar (Kab.)', 69000001, 'January 2026', 'BLUD', 1, 1, '1 TAHUN', 'Belanja Jasa Pembersihan, Pengendalian Hama, dan Fumigasi - Pest Control', 'SPESIFIKASI MUTU Pengendalian Vektor dan binatang pembawa penyakit, terdiri dari : 1. Pest Control / pengendalian hama secara umum terdiri dari : a. Inspeksi adalah metode pengecekan seluruh area untuk mengendalikan hama dengan cara menemukan tempat berkembangbiak b. Misting adalah pengendalian dengan menggunakan efek residual diarea tempat peristirahatan serangga c. Spraying adalah mengendalikan secara langsung dengan penyemprotan chemical dan memberikan efek residual pada suatu area d. Insect Light Monitoring adalah alat monitoring atau perangkap untuk serangga terbang 2. Rodent Control terdiri dari : a. Sistem Baiting / umpan adalah pengendalian hama tikus dengan memberikan umpan beracun b. Sistem Glue Trap adalah pengendalian hama tikus dengan menggunakan lem yang diberi umpan c. Sistem Lifetrap adalah pengendalian hama tikus dengan sistem non chemical 3. Uncommont Pest / hama tidak umum terdiri dari a. Cat Control adalah pemasangan perangkap kucing diarea tempat keberadaan kucing b. Snake trap adalah pemasangan perangkap ular SPESIFIKASI JENIS DAN JUMLAH No Uraian Keterangan 1 Hama Umum Tikus, Nyamuk, Lalat, Kecoa, Semut, Rayap, dan serangga lainnya 2. Hama Tidak Umum Kucing, Ular, Lebah SPESIFIKASI WAKTU 1. Waktu pelaksanaan pekerjaan : 1 tahun anggaran 2026 2. Lokasi kedatangan barang : Koordinasi dengan Kepala IPL (Instalasi Penyehatan Lingkungan) RSUD “Ngudi Waluyo” Wlingi Jl Dr Sucipto No. 5 Wlingi Kabupaten Blitar 3. Metode transportasi dan pengepakan : Diserahkan ke penyedia SPESIFIKASI PELAYANAN 1. Tingkat pelayanan jasa : - Manajemen respon time - Adanya jadwal pelaksanaan pekerjaan 2. Pelatihan dan Bantuan Teknis dari Penyedia Jasa : Disesuaikan dengan kondisi di lapangan 3. Pemeliharaan : Disesuaikan dengan kondisi di lapangan 4. Informasi lainnya terkait spesifikasi pelayanan : Persyaratan kualifikasi penyedia : a.Memiliki tenaga bersertifikat b.Memiliki Nomor Induk Berusaha (NIB) atau Tanda Daftar Perusahaan (TDP) yang masih berlaku. c.Memiliki Akta Pendirian Perusahaan yang masih berlaku d.Memiliki Dokumen Status Valid Wajib Pajak e. mempunyai atau menguasai tempat usaha/kantor dengan alamat yang benar, tetap dan jelas berupa milik sendiri atau sewa', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1808286);
